# -*- coding: utf-8 -*-
r"""
V9.4.1 - KHÓA DUY NHẤT QĐ 3805
================================

Theo yêu cầu nghiệp vụ:
- Chỉ sử dụng duy nhất QĐ 3805.
- Không tạo NHÁP.
- Không nhập thêm văn bản.
- Không sửa/phê duyệt/hủy phương án khác.
- Chỉ xem/đối chiếu 6 nhóm nguồn -> đích QĐ 3805 đã chốt.
- Backend từ chối mọi mutation phương án khi SINGLE_DOCUMENT_LOCK bật.

Bản cài:
- KHÔNG sửa database.
- KHÔNG sửa file school_merger_approved_plans.json.
- Chỉ sửa service + 2 template.
- Kiểm tra SHA256 đúng nền V9.4 trước khi ghi.
- Backup mã nguồn trước khi cài.
- Nếu lỗi cú pháp/Jinja sau cài, tự khôi phục file cũ.
"""

from __future__ import annotations

import ast
import base64
import hashlib
import shutil
import sys
import zlib
from datetime import datetime
from pathlib import Path

ROOT = Path(r"C:\PhoCap")
SERVICE = ROOT / "app" / "services" / "school_merger_service.py"
MAIN_TEMPLATE = ROOT / "app" / "templates" / "data_tools" / "school_merger.html"
PLANS_TEMPLATE = ROOT / "app" / "templates" / "data_tools" / "school_merger_plans.html"
PLAN_FILE = ROOT / "data" / "school_merger_approved_plans.json"
EXPORTS = ROOT / "exports"

EXPECTED = {
    str(SERVICE): '8f8e9f6e68e87da944ae61a30b52c864cf82efb3907c8835d29c061e25b81588',
    str(MAIN_TEMPLATE): 'f5b1d7b973e3434b1c96dd83b4fe1cac96b5bc736b9e30d4cf73bb7c4b019d88',
    str(PLANS_TEMPLATE): '091a12898aac789a24d30dac94e947be9b1d7312036d601569b9d10cbc369e94',
}

BLOBS = {
    str(SERVICE): '',
    str(MAIN_TEMPLATE): '',
    str(PLANS_TEMPLATE): '',
}


def decode(value: str) -> bytes:
    return zlib.decompress(base64.b64decode(value.encode("ascii")))


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def fail(message: str, code: int = 2) -> None:
    print("=" * 108)
    print("DỪNG AN TOÀN V9.4.1")
    print("=" * 108)
    print(message)
    print("Database KHÔNG bị thay đổi.")
    print("File phương án KHÔNG bị thay đổi.")
    raise SystemExit(code)


def main() -> None:
    for path in (SERVICE, MAIN_TEMPLATE, PLANS_TEMPLATE):
        if not path.exists():
            fail(f"Không tìm thấy file nền V9.4: {path}")

    # Chỉ cài đúng lên bản V9.4 vừa kiểm tra.
    mismatches = []
    for path_text, expected_hash in EXPECTED.items():
        path = Path(path_text)
        actual = sha(path)
        if actual != expected_hash:
            mismatches.append(
                f"{path}\n  expected={expected_hash}\n  actual  ={actual}"
            )
    if mismatches:
        fail(
            "Mã nguồn hiện tại không khớp đúng nền V9.4 dùng để tạo V9.4.1. "
            "Không vá đoán.\n\n" + "\n\n".join(mismatches),
            3,
        )

    plan_before = PLAN_FILE.read_bytes() if PLAN_FILE.exists() else None

    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_dir = EXPORTS / f"backup_sap_nhap_v9_4_1_{stamp}"
    backup_dir.mkdir(parents=True, exist_ok=False)

    shutil.copy2(SERVICE, backup_dir / SERVICE.name)
    shutil.copy2(MAIN_TEMPLATE, backup_dir / MAIN_TEMPLATE.name)
    shutil.copy2(PLANS_TEMPLATE, backup_dir / PLANS_TEMPLATE.name)

    try:
        SERVICE.write_bytes(decode(BLOBS[str(SERVICE)]))
        MAIN_TEMPLATE.write_bytes(decode(BLOBS[str(MAIN_TEMPLATE)]))
        PLANS_TEMPLATE.write_bytes(decode(BLOBS[str(PLANS_TEMPLATE)]))

        ast.parse(SERVICE.read_text(encoding="utf-8"))

        try:
            from jinja2 import Environment
            env = Environment()
            env.parse(MAIN_TEMPLATE.read_text(encoding="utf-8"))
            env.parse(PLANS_TEMPLATE.read_text(encoding="utf-8"))
            jinja_status = "PASS"
        except ImportError:
            jinja_status = "SKIP - jinja2 không có trong Python installer"

        service_text = SERVICE.read_text(encoding="utf-8")
        main_text = MAIN_TEMPLATE.read_text(encoding="utf-8")
        plans_text = PLANS_TEMPLATE.read_text(encoding="utf-8")

        checks = {
            "single document lock": "SINGLE_DOCUMENT_LOCK = True" in service_text,
            "exact six plan ids": "QD3805-NGHI-LOC-THCS-NGHI-TRUNG" in service_text,
            "mutation hard blocked": "Hệ thống đã khóa chỉ sử dụng duy nhất QĐ 3805" in service_text,
            "main button read-only": "Xem phương án QĐ 3805" in main_text,
            "readonly plans page": "Không tạo NHÁP, không nhập thêm văn bản" in plans_text,
            "no draft UI": "Lưu phương án NHÁP" not in plans_text,
            "no approve UI": "PHÊ DUYỆT" not in plans_text,
        }
        failed = [name for name, ok in checks.items() if not ok]
        if failed:
            raise RuntimeError("Thiếu marker sau cài: " + ", ".join(failed))

        # Bắt buộc không thay đổi file phương án.
        plan_after = PLAN_FILE.read_bytes() if PLAN_FILE.exists() else None
        if plan_before != plan_after:
            raise RuntimeError(
                "File school_merger_approved_plans.json đã thay đổi ngoài dự kiến."
            )

    except Exception as exc:
        shutil.copy2(backup_dir / SERVICE.name, SERVICE)
        shutil.copy2(backup_dir / MAIN_TEMPLATE.name, MAIN_TEMPLATE)
        shutil.copy2(backup_dir / PLANS_TEMPLATE.name, PLANS_TEMPLATE)
        print("=" * 108)
        print("CÀI V9.4.1 THẤT BẠI - ĐÃ TỰ KHÔI PHỤC")
        print("=" * 108)
        print(repr(exc))
        print("Database KHÔNG bị thay đổi.")
        print("File phương án KHÔNG bị thay đổi.")
        raise SystemExit(5)

    report = backup_dir / "00_KET_QUA_CAI_DAT_V9_4_1.txt"
    report.write_text(
        "\n".join([
            "V9.4.1 - KHÓA DUY NHẤT QĐ 3805",
            "=" * 80,
            "STATUS=SUCCESS",
            "Database=KHÔNG THAY ĐỔI",
            "File phương án=KHÔNG THAY ĐỔI",
            f"Backup={backup_dir}",
            f"Jinja={jinja_status}",
            "",
            "Đã khóa:",
            "- Chỉ 6 nhóm QĐ 3805 đã chốt.",
            "- Không tạo NHÁP.",
            "- Không nhập văn bản mới.",
            "- Không sửa/phê duyệt/hủy plan khác.",
            "- Backend mutation cũng bị chặn.",
            "- Trang phương án chỉ xem/đối chiếu.",
        ]),
        encoding="utf-8",
    )

    print("=" * 108)
    print("CÀI ĐẶT V9.4.1 THÀNH CÔNG")
    print("=" * 108)
    print("Database: KHÔNG THAY ĐỔI")
    print("File phương án: KHÔNG THAY ĐỔI")
    print(f"Backup mã nguồn: {backup_dir}")
    print(f"Jinja parse: {jinja_status}")
    print("Chỉ sử dụng duy nhất QĐ 3805.")
    print("Đã bỏ giao diện NHÁP / PHÊ DUYỆT / nhập văn bản mới.")
    print("Backend đã khóa mọi mutation phương án.")
    print("Nút mới: Xem phương án QĐ 3805")


if __name__ == "__main__":
    main()
